import {initialTasks,projects as initialProjects,type Task} from './data';
export const scenarios=[{id:'normal',name:'Normal'},{id:'few',name:'Poucas tarefas'},{id:'many',name:'Muitas tarefas'},{id:'long',name:'Textos longos'},{id:'dates',name:'Prazos'},{id:'empty',name:'Vazio'},{id:'loading',name:'Carregando'},{id:'error',name:'Erro de carregamento'}] as const;
export type ScenarioId=typeof scenarios[number]['id'];
const calendarDay=(offset=0)=>{const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Araguaina',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const part=(key:string)=>Number(parts.find(p=>p.type===key)?.value);const date=new Date(Date.UTC(part('year'),part('month')-1,part('day')+offset));return date.toISOString().slice(0,10)};
export function scenarioData(id:ScenarioId){let tasks:Task[]=initialTasks.map(t=>({...t}));const projects=initialProjects.map(p=>({...p}));if(id==='few')tasks=[{...tasks[0]}];if(id==='many')tasks=Array.from({length:28},(_,i)=>({...initialTasks[i%5],id:`demo-${i+1}`,titulo:`${initialTasks[i%5].titulo} · ${i+1}`,status:['a-fazer','em-andamento','em-revisao','concluida'][i%4],prioridade:['alta','media','baixa'][i%3]}));if(id==='long'){projects[0].nome='Desenvolvimento da experiência de organização e acompanhamento das entregas acadêmicas';tasks=tasks.map((t,i)=>({...t,titulo:i===0?'Revisar os critérios de aceitação e a experiência completa dos formulários de criação e edição de tarefas com toda a equipe':t.titulo,responsavel:i===0?'Ana Carolina de Oliveira':t.responsavel,descricao:Array.from({length:6},()=> 'Registrar o contexto da entrega, conferir os critérios de aceitação e organizar as referências para que a equipe consiga acompanhar o próximo passo.\n\n').join('')}))}if(id==='dates')tasks=tasks.map((t,i)=>({...t,prazo:calendarDay([-1,0,1,-2,3][i])}));return {tasks:id==='empty'?[]:tasks,projects:id==='empty'?[]:projects}}
