 useEffect(()=>{let timer:ReturnType<typeof setTimeout>;const schedule=()=>{const now=new Date();const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'America/Araguaina',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(now);const part=(type:string)=>Number(parts.find(p=>p.type===type)?.value);const elapsed=(part('hour')*3600+part('minute')*60+part('second'))*1000+now.getMilliseconds();timer=setTimeout(()=>{setToday(localDay());schedule()},86400000-elapsed+25)};schedule();return()=>clearTimeout(timer)},[]);
