 function revealActiveProject(focus=false){const active=document.querySelector<HTMLElement>(`.e-tabs [data-project="${CSS.escape(project)}"]`);const strip=active?.parentElement;if(!active||!strip)return;const box=active.getBoundingClientRect(),area=strip.getBoundingClientRect();if(box.left<area.left)strip.scrollLeft+=box.left-area.left-4;else if(box.right>area.right)strip.scrollLeft+=box.right-area.right+4;if(focus)active.focus({preventScroll:true})}
 function dismissNotice(inline:boolean){const focused=inline&&Boolean(document.activeElement?.closest('.e-notice-inline'));setNotice('');setPanelNotice('');if(focused)requestAnimationFrame(()=>document.querySelector<HTMLElement>('.e-form-header button,.e-delete-actions button')?.focus({preventScroll:true}))}
 function noticeBanner(inline=false){const message=inline?panelNotice:notice;if(!message)return null;const close=<Button color="tertiary" size="sm" aria-label="Fechar aviso" onClick={()=>dismissNotice(inline)}><Icon name="cross-small"/></Button>;return <div role="status" aria-hidden={inline&&!modalOpen&&!deleteTarget?true:undefined} className={inline?'e-notice-inline':'e-notice'}><span className="e-notice-check"><CheckIcon/></span><span>{message}</span>{inline?close:<Tooltip title="Fechar aviso">{close}</Tooltip>}</div>}
 function openNew(){setPanelNotice(notice);const context=`new:${project}`;trigger.current=document.activeElement as HTMLElement;const value=drafts.current[context]||blank(project);setDraft({...value});setDescription(Boolean(value.descricao));setErrors({});setSaveError('');setModal({kind:'new',context});setModalOpen(true)}
 function restoreOrigin(){const taskId=modal?.taskId;const projectId=modal?.projectId;const projectOrigin=projectForm;const originClass=trigger.current?.classList.contains('e-task-menu')?'.e-task-menu':'.e-task-title';requestAnimationFrame(()=>{const remounted=taskId?document.querySelector<HTMLElement>(`[data-task-id="${CSS.escape(taskId)}"] ${originClass}`):null;const projectTrigger=projectId?document.querySelector<HTMLElement>(`[data-project-id="${CSS.escape(projectId)}"] .e-edit-project`):null;const target=trigger.current?.isConnected?trigger.current:remounted||projectTrigger; if(target)target.focus();else document.querySelector<HTMLElement>(projectOrigin?'[data-action="new-project"]':'[data-action="new-task"]')?.focus()})}
