 function closeForm(){if(!modal||!modalOpen)return;if(projectForm)projectDrafts.current[modal.context]={...projectDraft};else if(modal.kind!=='read')drafts.current[modal.context]={...draft};if(pending.current)clearTimeout(pending.current);pending.current=null;setSaving(false);if(modal.kind==='edit'&&modal.fromDetails){setModal({kind:'read',context:`read:${modal.taskId}`,taskId:modal.taskId});requestAnimationFrame(()=>document.querySelector<HTMLElement>('.e-read-edit')?.focus())}else{setModalOpen(false);restoreOrigin()}}
 function openProjectForm(value?:Project){setPanelNotice(notice);const context=value?`project-edit:${value.id}`:'project-new';trigger.current=document.activeElement as HTMLElement;setProjectDraft({...projectDrafts.current[context]||value||blankProject()});setErrors({});setSaveError('');setModal({kind:value?'project-edit':'project-new',context,projectId:value?.id});setModalOpen(true)}
