 function submitProject(event:FormEvent){event.preventDefault();if(saving||!modalOpen||!modal||!projectForm)return;const next:Record<string,string>={};if(!projectDraft.nome.trim())next.nome='Informe o nome do projeto.';if(!projectDraft.disciplina.trim())next.disciplina='Informe a disciplina.';setErrors(next);if(Object.keys(next).length){requestAnimationFrame(()=>document.querySelector<HTMLElement>('.e-project-form [aria-invalid="true"]')?.focus());return}setSaving(true);setSaveError('');const context=modal.context;const creating=modal.kind==='project-new';const value={...projectDraft,nome:projectDraft.nome.trim(),disciplina:projectDraft.disciplina.trim()};pending.current=setTimeout(()=>{pending.current=null;setSaving(false);if(failure.current){failure.current=false;setSaveError('Não foi possível salvar o projeto. Seus dados continuam aqui. Tente novamente.');return}if(creating){setProjects(ps=>[...ps,{...value,id:crypto.randomUUID(),criadoEm:localDay()}]);setSection('projects');setNotice('Projeto criado.')}else{setProjects(ps=>ps.map(p=>p.id===value.id?{...value,id:p.id,criadoEm:p.criadoEm}:p));setNotice('Projeto atualizado.')}delete projectDrafts.current[context];setModalOpen(false);restoreOrigin()},700)}
