 function applyScenario(id:ScenarioId,reset:boolean){if(pending.current)clearTimeout(pending.current);pending.current=null;setSaving(false);setDeleting(false);setDeleteTarget(null);setModalOpen(false);setModal(null);setErrors({});setSaveError('');setDeleteError('');setNotice('');setPanelNotice('');drafts.current={};projectDrafts.current={};readScroll.current={};setDraft(blank('all'));setProjectDraft(blankProject());setTaskTarget(null);clear();setFilters(false);setDetails(false);setProject('all');const data=scenarioData(id);fixtureSignature.current=JSON.stringify(data);setTasks(data.tasks);setProjects(data.projects);setScenario(id);setHeldLoading(id==='loading');setLoading(id==='loading');setLoadError(id==='error');failure.current=false;deleteFailure.current=false;if(reset){setPalette('ameixa');setDark(false);setSection('tasks');setLayout('list')}requestAnimationFrame(()=>requestAnimationFrame(()=>{window.scrollTo({top:0,behavior:'instant'});document.querySelector<HTMLElement>(section==='projects'&&!reset?'[data-action="new-project"]':'[data-search] input,input[data-search],[data-action="new-task"]')?.focus({preventScroll:true})}))}
