 function confirmDelete(){if(!deleteTarget||deleting)return;setDeleting(true);setDeleteError('');const id=deleteTarget.id;pending.current=setTimeout(()=>{pending.current=null;setDeleting(false);if(deleteFailure.current){deleteFailure.current=false;setDeleteError('Não foi possível excluir a tarefa. Tente novamente.');return}setTasks(ts=>ts.filter(t=>t.id!==id));setDeleteTarget(null);setNotice('Tarefa excluída.');requestAnimationFrame(()=>document.querySelector<HTMLElement>('.e-task-menu,[data-action="new-task"]')?.focus())},700)}
