 function submit(event:FormEvent){event.preventDefault();if(saving||!modalOpen||!modal||modal.kind==='read'||projectForm)return;const next:Record<string,string>={};if(!draft.titulo.trim())next.titulo='Dê um título à tarefa.';if(!projects.some(p=>p.id===draft.projetoId))next.projetoId='Escolha um projeto.';if(!draft.responsavel.trim())next.responsavel='Informe o responsável.';if(!/^\d{4}-\d{2}-\d{2}$/.test(draft.prazo)||Number.isNaN(new Date(draft.prazo+'T12:00:00').valueOf()))next.prazo='Informe um prazo válido.';if(!draft.status)next.status='Escolha o status.';if(!draft.prioridade)next.prioridade='Escolha a prioridade.';setErrors(next);if(Object.keys(next).length){requestAnimationFrame(()=>document.querySelector<HTMLElement>('.e-task-form [aria-invalid="true"]')?.focus());return}setSaveError('');setSaving(true);const context=modal.context;const kind=modal.kind;const fromDetails=modal.fromDetails;const taskId=modal.taskId;const value={...draft,titulo:draft.titulo.trim(),responsavel:draft.responsavel.trim()};pending.current=setTimeout(()=>{pending.current=null;setSaving(false);if(failure.current){failure.current=false;setSaveError('Não foi possível salvar a tarefa. Seus dados continuam aqui. Tente novamente.');return}if(kind==='new'){setTasks(ts=>[...ts,{...value,id:String(Date.now())}]);setProject('all');setLayout('list');setSection('tasks');clear();setNotice('Tarefa criada.')}else{setTasks(ts=>ts.map(t=>t.id===value.id?value:t));setNotice('Alterações salvas.');if(fromDetails)setPanelNotice('Alterações salvas.')}delete drafts.current[context];if(fromDetails){setModal({kind:'read',context:`read:${taskId}`,taskId});requestAnimationFrame(()=>document.querySelector<HTMLElement>('.e-read-edit')?.focus())}else{setModalOpen(false);restoreOrigin()}},700)}
 function taskAction(task:Task,key:string){if(key==='edit')openEdit(task);if(key.startsWith('status:')){const next=key.slice(7);if(statuses.some(s=>s.id===next)){setTasks(ts=>ts.map(t=>t.id===task.id?{...t,status:next}:t));setNotice('Status atualizado.');requestAnimationFrame(()=>{const target=document.querySelector<HTMLElement>(`[data-task-id="${CSS.escape(task.id)}"] .e-task-menu`);(target||document.querySelector<HTMLElement>('[data-action="new-task"]'))?.focus()})}}if(key==='complete'){setTasks(ts=>ts.map(t=>t.id===task.id?{...t,status:task.status==='concluida'?'a-fazer':'concluida'}:t));setNotice(task.status==='concluida'?'Tarefa reaberta.':'Tarefa concluída.')}if(key==='delete'){setPanelNotice(notice);setDeleteError('');setDeleting(false);trigger.current=document.querySelector(`[data-task-id="${task.id}"] .e-task-menu`);setDeleteTarget(task)}}
