 function taskCard(task:Task){const board=layout==='board';const done=task.status==='concluida';const highOpen=board&&!done&&task.prioridade==='alta';const due=board&&!done?dueState(task.prazo,today):null;const priorityBadge=<Badge key="priority" type="modern" size="sm" color="gray" className={`e-priority e-priority-${task.prioridade}`}><Icon name={task.prioridade==='alta'?'angle-double-small-up':task.prioridade==='baixa'?'arrow-small-down':'minus-small'}/>{label(priorities,task.prioridade)}</Badge>;const statusBadge=<BadgeWithDot key="status" type="pill-color" size="sm" color={task.status==='concluida'?'success':task.status==='a-fazer'?'gray':'brand'} className={`e-status e-status-${task.status}`}>{label(statuses,task.status)}</BadgeWithDot>;return <article key={task.id} className={`e-task ${board?`e-card${highOpen?' e-card-high':''}${done?' e-card-done':''}`:'e-row'}`} data-task-id={task.id} data-due-state={due||undefined}><div className="e-task-main"><div className="e-task-heading"><button className="e-task-title" onClick={()=>openRead(task)}>{task.titulo}</button>{taskMenu(task)}</div>{project==='all'&&<span className="e-task-project"><FolderIcon/>{projects.find(p=>p.id===task.projetoId)?.nome}</span>}<div className="e-task-meta"><span><Icon name="user"/>{task.responsavel}</span><span className={due?`e-due-date e-due-${due}`:undefined}><Icon name="calendar"/>{due?<span><strong>{due==='overdue'?'Prazo vencido':'Vence hoje'}</strong> <time dateTime={task.prazo}>({dateLabel(task.prazo)})</time></span>:dateLabel(task.prazo)}</span></div></div><div className="e-task-tags">{layout==='list'?[statusBadge,priorityBadge]:[priorityBadge,statusBadge]}</div></article>}
