import {useEffect,useRef,useState} from 'react';
import {Button,Dialog,DialogTrigger,Heading,Popover} from 'react-aria-components';
import {palettes} from './palettes';
import {scenarios,type ScenarioId} from './dev-scenarios';
import './dev-tools.css';
type Props={palette:string;dark:boolean;scenario:ScenarioId;dirty:boolean;blocked:boolean;failSave:boolean;failDelete:boolean;onPalette:(id:string)=>void;onDark:(dark:boolean)=>void;onApply:(id:ScenarioId,reset:boolean)=>void;onFailure:(kind:'save'|'delete',value:boolean)=>void};
export function DevTools(props:Props){const [open,setOpen]=useState(false);const [selection,setSelection]=useState<ScenarioId>(props.scenario);const [confirmation,setConfirmation]=useState<{id:ScenarioId;reset:boolean}|null>(null);const trigger=useRef<HTMLButtonElement>(null);useEffect(()=>{setSelection(props.scenario)},[props.scenario]);useEffect(()=>{const handler=(event:KeyboardEvent)=>{const target=event.target as HTMLElement;if(event.altKey&&event.shiftKey&&event.code==='KeyD'&&!props.blocked&&!target.closest('input,textarea,select,[contenteditable=true]')){event.preventDefault();trigger.current?.scrollIntoView({block:'nearest'});setOpen(v=>!v)}};document.addEventListener('keydown',handler);return()=>document.removeEventListener('keydown',handler)},[props.blocked]);function apply(id:ScenarioId,reset=false){if(props.dirty){setConfirmation({id,reset});return}commit(id,reset)}function commit(id:ScenarioId,reset:boolean){props.onApply(id,reset);setSelection(id);setConfirmation(null);setOpen(false)}function changeOpen(value:boolean){setOpen(value);if(!value)setConfirmation(null)}const chosen=palettes.find(p=>p.id===props.palette)||palettes[0];return <DialogTrigger isOpen={open} onOpenChange={changeOpen}><Button ref={trigger} className="e-dev-trigger" isDisabled={props.blocked}>Testar design{props.scenario!=='normal'&&<span className="e-dev-active"> · {scenarios.find(s=>s.id===props.scenario)?.name}</span>}</Button><Popover placement="top end" offset={8} className="e-dev-popover"><Dialog className="e-dev-dialog" aria-label="Testar design">{({close})=><><header className="e-dev-header"><Heading slot="title">Testar design</Heading><Button className="e-dev-close" aria-label="Fechar testes de design" onPress={close}>×</Button></header><p className="e-dev-caption">Só nesta prévia; recarregar restaura o padrão.</p><p className="e-dev-current">Situação atual: <strong>{scenarios.find(s=>s.id===props.scenario)?.name}</strong></p><div className="e-dev-body"><label className="e-dev-field"><span>Paleta</span><select value={props.palette} onChange={e=>props.onPalette(e.target.value)}>{palettes.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><div className="e-dev-swatches" aria-hidden="true">{chosen.swatches.map((color,i)=><span key={i} style={{backgroundColor:color}}/>)}</div><fieldset className="e-dev-theme"><legend>Tema</legend><button type="button" aria-pressed={!props.dark} onClick={()=>props.onDark(false)}>Claro</button><button type="button" aria-pressed={props.dark} onClick={()=>props.onDark(true)}>Escuro</button></fieldset><div className="e-dev-scenario"><label className="e-dev-field"><span>Situação</span><select value={selection} onChange={e=>{setSelection(e.target.value as ScenarioId);setConfirmation(null)}}>{scenarios.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><button type="button" onClick={()=>apply(selection)}>Aplicar</button></div><p className="e-dev-help">Aplicar uma situação restaura os dados demonstrativos e limpa filtros e rascunhos.</p><fieldset className="e-dev-failures"><legend>Próxima tentativa</legend><label><input type="checkbox" checked={props.failSave} onChange={e=>props.onFailure('save',e.target.checked)}/>Falhar ao salvar</label><label><input type="checkbox" checked={props.failDelete} onChange={e=>props.onFailure('delete',e.target.checked)}/>Falhar ao excluir</label></fieldset>{confirmation&&<div className="e-dev-confirm" role="alert"><p>Há alterações ou rascunhos nesta prévia. Substituir pelos dados demonstrativos?</p><div><button autoFocus type="button" onClick={()=>setConfirmation(null)}>Manter alterações</button><button type="button" onClick={()=>commit(confirmation.id,confirmation.reset)}>Substituir dados</button></div></div>}<button type="button" className="e-dev-reset" onClick={()=>apply('normal',true)}>Restaurar padrão</button></div><p className="e-dev-shortcut">Alt + Shift + D abre este menu fora dos campos.</p></>}</Dialog></Popover></DialogTrigger>}
